entries[386270] = { ["name"] = "Unverfroren", ["text"] = "Sofort\nNutzt die Verwundbarkeit von Gegnern mit weniger als 35% Gesundheit aus und fügt dem Ziel (60% der Angriffskraft) körperlichen Schaden zu.\n\n'Verstümmeln' hat eine Chance von 25%, Euren nächsten Einsatz von 'Wunder Punkt' kostenlos und gegen jedes Ziel, unabhängig von seiner Gesundheit, einsetzbar zu machen.\n\nGewährt 1 Combopunkt." }
