entries[386274] = { ["name"] = "Knochenstaubgebräu", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchleudert ein aus den Knochen Eurer Gegner hergestelltes Gebräu auf den Boden, das alle getroffenen Ziele für 10 Sek. bedeckt. Eure Fähigkeiten haben eine Chance von 50%, sich mit 40% Effektivität ein zweites Mal als Schattenschaden oder Heilung auf das Ziel auszuwirken.\n\n[ Nebelwirker : 'Nebelschwall' heilt alle Ziele, bei denen Euer Knochenstaubgebräu aktiv ist, um zusätzlich (42% der Angriffskraft) Gesundheit / Braumeister : 'Tigerklaue' und 'Fasshieb' verringern die Abklingzeiten Eurer Gebräue um zusätzlich 1 Sek., wenn Ihr Gegner angreift, bei denen Euer Knochenstaubgebräu aktiv ist / Windläufer : 'Wirbelnder Kranichtritt' erstattet 1 Chi, wenn Ihr Gegner angreift, bei denen Euer Knochenstaubgebräu aktiv ist ]" }
entries[386275] = { ["name"] = "Knochenstaubgebräu", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchleudert ein aus den Knochen Eurer Gegner hergestelltes Gebräu auf den Boden, das alle getroffenen Ziele für 10 Sek. bedeckt. Eure Fähigkeiten haben eine Chance von 50%, sich mit 40% Effektivität ein zweites Mal als Schattenschaden oder Heilung auf das Ziel auszuwirken.\n\n[ Nebelwirker : 'Nebelschwall' heilt alle Ziele, bei denen Euer Knochenstaubgebräu aktiv ist, um zusätzlich (42% der Angriffskraft) Gesundheit / Braumeister : 'Tigerklaue' und 'Fasshieb' verringern die Abklingzeiten Eurer Gebräue um zusätzlich 1 Sek., wenn Ihr Gegner angreift, bei denen Euer Knochenstaubgebräu aktiv ist / Windläufer : 'Wirbelnder Kranichtritt' erstattet 1 Chi, wenn Ihr Gegner angreift, bei denen Euer Knochenstaubgebräu aktiv ist ]" }
entries[386276] = { ["name"] = "Knochenstaubgebräu", ["text"] = "40 Meter Reichweite\nSofort 1 min Abklingzeit\nNebelwirker ( Nebelwirkermönch )\nSchleudert ein aus den Knochen Eurer Gegner hergestelltes Gebräu auf den Boden, das alle getroffenen Ziele für 10 Sek. bedeckt. Eure Fähigkeiten haben eine Chance von 50%, sich mit 50% Effektivität ein zweites Mal als Schattenschaden oder Heilung auf das Ziel auszuwirken.\n\n'Nebelschwall' heilt alle Ziele, bei denen Euer Knochenstaubgebräu aktiv ist, um zusätzlich (42% der Angriffskraft) Gesundheit.\n\nBraumeister, Windläufer\nSchleudert ein aus den Knochen Eurer Gegner hergestelltes Gebräu auf den Boden, das alle getroffenen Ziele für 10 Sek. bedeckt. Eure Fähigkeiten haben eine Chance von 50%, sich mit 40% Effektivität ein zweites Mal als Schattenschaden oder Heilung auf das Ziel auszuwirken.\n\n[ Nebelwirker : 'Nebelschwall' heilt alle Ziele, bei denen Euer Knochenstaubgebräu aktiv ist, um zusätzlich (42% der Angriffskraft) Gesundheit / Braumeister : 'Tigerklaue' und 'Fasshieb' verringern die Abklingzeiten Eurer Gebräue um zusätzlich 1 Sek., wenn Ihr Gegner angreift, bei denen Euer Knochenstaubgebräu aktiv ist / Windläufer : 'Wirbelnder Kranichtritt' erstattet 1 Chi, wenn Ihr Gegner angreift, bei denen Euer Knochenstaubgebräu aktiv ist / Großzügiges Gebräu : Eure Fähigkeiten haben eine geringe Chance, 'Knochenstaubgebräu' an der Position Eures Ziels einzusetzen. ] [ Abschwächung : Wenn 'Knochenstaubgebräu' Schattenschaden oder Heilung verursacht, wird die Abklingzeit der Fähigkeit um 0.5 Sek. verringert ](Procchance: 50%)" }
entries[386277] = { ["name"] = "Resonierende Vernichtung", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn Terros 100 Energie erreicht, entfesselt er seine volatile Macht mit einem brutalen Hieb.\n\nDer Hieb fügt allen Spielercharakteren in einem kegelförmigen Bereich vor Terros 703095 Naturschaden zu, vernichtet Bereiche von ' Erweckte Erde ' und hinterlässt ' Resonierende Nachwirkung ' in seiner Bahn.\n\nDie Höhle zerbirst durch den Einschlags. Fügt allen Spielercharakteren 67130 Naturschaden zusätzlich zu, während ' Gesprungener Schutt ' von der Decke fällt." }
