entries[387153] = { ["name"] = "Zu Asche verbrennen", ["text"] = "'Chaosblitz' und 'Feuerregen' erhöhen den Schaden bei Euren nächsten 2 Einsätzen von 'Verbrennen' um 15%. 'Schattenbrand' erhöht den Schaden Eures nächsten Einsatzes von 'Verbrennen' um 15%.\n\nBis zu 6-mal stapelbar." }
entries[387154] = { ["name"] = "Zu Asche verbrennen", ["text"] = "Sofort\n'Chaosblitz' und 'Feuerregen' erhöhen den Schaden bei Euren nächsten 2 Einsätzen von 'Verbrennen' um 15%. 'Schattenbrand' erhöht den Schaden Eures nächsten Einsatzes von 'Verbrennen' um 15%.\n\nBis zu 6-mal stapelbar." }
