entries[387156] = { ["name"] = "Ritual des Ruins", ["text"] = "Nach 20 verbrauchten Seelensplittern erhaltet Ihr 'Ritual des Ruins', wodurch Euer nächster Einsatz von 'Chaosblitz' oder 'Feuerregen' keine Seelensplitter verbraucht und eine um 50% verringerte Zauberzeit hat." }
entries[387157] = { ["name"] = "Ritual des Ruins", ["text"] = "Sofort\nNach 20 verbrauchten Seelensplittern erhaltet Ihr 'Ritual des Ruins', wodurch Euer nächster Einsatz von 'Chaosblitz' oder 'Feuerregen' keine Seelensplitter verbraucht und eine um 50% verringerte Zauberzeit hat.\n(750ms Abklingzeit)" }
entries[387158] = { ["name"] = "Bevorstehender Ruin", ["text"] = "Sofort\nNach 20 verbrauchten Seelensplittern erhaltet Ihr 'Ritual des Ruins', wodurch Euer nächster Einsatz von 'Chaosblitz' oder 'Feuerregen' keine Seelensplitter verbraucht und eine um 50% verringerte Zauberzeit hat." }
entries[387159] = { ["name"] = "Avatar der Zerstörung", ["text"] = "Wenn 'Chaosblitz' oder 'Feuerregen' eine Aufladung von 'Ritual des Ruins' verbrauchen, beschwört Ihr für 8 Sek. eine Blasphemie.\n\nBlasphemie\nBeschwört eine Blasphemie aus dem Wirbelnden Nether, die beim Einschlag (60% der Zaubermacht) Feuerschaden verursacht und alle Gegner im Effektbereich für 2 Sek. betäubt.\n\nDie Blasphemie steht 8 Sek. lang unter Eurem Befehl, fügt allen Gegnern in der Nähe alle 2 Sek. [(55% der Zaubermacht) * 111 / 100] Schaden zu und erzeugt alle 1 Sek. 1 Seelensplitterfragment." }
entries[387160] = { ["name"] = "Blasphemie beschwören", ["text"] = "2% von Grundmana 100 Meter Reichweite\nSofort\nBeschwört eine Blasphemie aus dem Wirbelnden Nether, die beim Einschlag (60% der Zaubermacht) Feuerschaden verursacht und alle Gegner im Effektbereich für 2 Sek. betäubt.\n\nDie Blasphemie steht 8 Sek. lang unter Eurem Befehl, fügt allen Gegnern in der Nähe alle 2 Sek. [(55% der Zaubermacht) * (111) / 100] Schaden zu und erzeugt alle 1 Sek. 1 Seelensplitterfragment." }
entries[387161] = { ["name"] = "Blasphemie", ["text"] = "Unbegrenzte Reichweite\nSofort\nBeschwört eine Blasphemie aus dem Wirbelnden Nether, die beim Einschlag (60% der Zaubermacht) Feuerschaden verursacht und alle Gegner im Effektbereich für 2 Sek. betäubt.\n\nDie Blasphemie steht 8 Sek. lang unter Eurem Befehl, fügt allen Gegnern in der Nähe alle 2 Sek. [(55% der Zaubermacht) * 111 / 100] Schaden zu und erzeugt alle 1 Sek. 1 Seelensplitterfragment." }
entries[387162] = { ["name"] = "Blasphemische Existenz", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Blasphemie entzündet sich und fügt allen Zielen (60% der Zaubermacht) Schattenflammenschaden zu." }
entries[387163] = { ["name"] = "Wasserdruck!", ["text"] = "20 Meter Reichweite\nWirken in 0.5 sek.\nEntfesselt den Wasserdruck, der sich in Euch aufbaut, und fügt einem Schwefelwüterich 25 Naturschaden zu." }
