entries[387168] = { ["name"] = "Segen der Pakte", ["text"] = "Pakt-Fähigkeit\nSofort 2 min Abklingzeit\nRuft die Pakte der Schattenlande zu Hilfe, stellt (600% der Zaubermacht) Gesundheit wieder her und erhöht Eure Vielseitigkeit 12 Sek. lang um 10%.\n\nPassiv: Die Pakte haben Euch einen Teil ihrer Macht gewährt, was Euren Schaden und Eure Heilung um 4.0% erhöht." }
