entries[387170] = { ["name"] = "Himmlisches Erbe", ["text"] = "Vergeltung\n'Richturteil' ermächtigt Euren nächsten Einsatz einer Heilige Kraft verbrauchenden Einzelzielfähigkeit, sodass er automatisch 'Göttlicher Sturm' mit 15% höherer Effektivität aktiviert.\n\nDieser Effekt kann nur einmal alle 20 Sek. auftreten.\n\nHeilig\n'Richturteil' ermächtigt Euren nächsten Einsatz von 'Wort der Herrlichkeit', sodass er automatisch 'Licht der Morgendämmerung' mit 25% höherer Effektivität aktiviert.\n\nDieser Effekt kann nur einmal alle 20 Sek. auftreten." }
entries[387173] = { ["name"] = "Diabolische Glut", ["text"] = "'Verbrennen' erzeugt 100% zusätzliche Seelensplitterfragmente." }
entries[387174] = { ["name"] = "Auge von Tyr", ["text"] = "Sofort 1 min Abklingzeit\n1 Aufladung\nEntfesselt einen blendenden Lichtblitz aus Eurem Schild, der allen Gegnern innerhalb von 8 Metern (64.4318% der Angriffskraft) Heiligschaden zufügt und den Schaden, den sie Euch zufügen, 6 Sek. lang um 25% verringert." }
entries[387176] = { ["name"] = "Dezimierung", ["text"] = "Wenn Ihr 'Verbrennen' und 'Feuersbrunst' auf Ziele mit 35% oder weniger Gesundheit wirkt, wird für 10 Sek. die Abklingzeit von 'Seelenfeuer' um 5 Sek. und die Zauberzeit um 40% verringert." }
