entries[387178] = { ["name"] = "Himmlisches Erbe", ["text"] = "Sofort\n'Richturteil' ermächtigt Euren nächsten Einsatz [ Vergeltung : einer Heilige Kraft verbrauchenden Einzelzielfähigkeit, sodass er automatisch 'Göttlicher Sturm' /\n\nHeilig\nvon 'Wort der Herrlichkeit', sodass er automatisch 'Licht der Morgendämmerung' ] mit 25% höherer Effektivität aktiviert.\n\nDieser Effekt kann nur einmal alle 20 Sek. auftreten." }
entries[387179] = { ["name"] = "Waffen der Ordnung", ["text"] = "100 Meter Reichweite\nSofort\nBraumeister\nErhöht für die nächsten 30 Sek. Eure Meisterschaft um ( 0.924000025 * 10)%. Zusätzlich wird die Abklingzeit von 'Fasshieb' sofort abgeschlossen und von 'Fasshieb' getroffene Gegner erleiden 10 Sek. lang 8% mehr Schaden durch Euch. Dieser Effekt ist bis zu 4-mal stapelbar.\n\nWindläufer\nErhöht für die nächsten 30 Sek. Eure Meisterschaft um ( 2.3287499 * 10)%. Zusätzlich verringert 'Tritt der aufgehenden Sonne' die Chikosten 5 Sek. lang um 1 und 'Blackout-Tritt' verringert die Abklingzeit betroffener Fähigkeiten um zusätzlich 1 Sek.\n\nNebelwirker\nErhöht für die nächsten 30 Sek. Eure Meisterschaft um ( 6.92999983 * 10)%. Zusätzlich wird die Abklingzeit von 'Essenzborn' sofort abgeschlossen und 'Essenzborn' heilt bis zu 6 Verbündete in der Nähe zu Beginn und am Ende der Kanalisierung um (40% der Zaubermacht) Gesundheit." }
entries[387180] = { ["name"] = "Dezimierung", ["text"] = "Wenn Ihr 'Verbrennen' und 'Feuersbrunst' auf Ziele mit 35% oder weniger Gesundheit wirkt, wird für 10 Sek. die Abklingzeit von 'Seelenfeuer' um 5 Sek. und die Zauberzeit um 40% verringert." }
