entries[387614] = { ["name"] = "Gesang der Toten", ["text"] = "10 Meter Reichweite\nWirken in 8 sek.\nFügt allen Spielercharakteren innerhalb von 10 Metern 4848899 Schattenschaden zu. Erhöht den verursachten Schaden aller untoten Verbündeten innerhalb von 10 Metern um 20% und verringert ihren erlittenen Schaden für 20 Sek. um 20%." }
entries[387615] = { ["name"] = "Griff der Toten", ["text"] = "50 Meter Reichweite\nWirken in 3 sek.\nVerringert die Bewegungsgeschwindigkeit des anvisierten Spielercharakters um 50% und fügt ihm 6 Sek. lang pro Sekunde 5 Schattenschaden zu.\n\nNach 6 Sek. wird der Spielercharakter für 5 Sek. bewegungsunfähig." }
