entries[387617] = { ["name"] = "Segen der Pakte", ["text"] = "Sofort\nRuft die Pakte der Schattenlande zu Hilfe, stellt (600% der Zaubermacht) Gesundheit wieder her und erhöht Eure Vielseitigkeit 12 Sek. lang um 10%.\n\nPassiv: Die Pakte haben Euch einen Teil ihrer Macht gewährt, was Euren Schaden und Eure Heilung um 4.0% erhöht." }
entries[387618] = { ["name"] = "Infusion", ["text"] = "100 Meter Reichweite\nWirken in 5 sek.\nDie Einflößerin der Primalisten kanalisiert auf den urtümlichen Tsunami und erhöht dessen verursachten Schaden um 1%. Dieser Effekt stapelt sich alle 5 Sek. weiter, bis er unterbrochen wird." }
